/**
 * Globe: dotted land (generated by scripts/gen-geo.ts → src/data/geo/land-dots.json), an opaque
 * ocean sphere, a fresnel atmosphere (dark theme only), stacked city markers and screen-space
 * picking helpers (scenes3d.md A15).
 *
 * Coordinates: y up; lon 0 faces +z; east is +x when seen from +z (north up, east right).
 * The land-dot JSON is loaded lazily as its own chunk (`await Globe.create(...)`).
 */
import {
  AdditiveBlending,
  BackSide,
  CircleGeometry,
  Color,
  CylinderGeometry,
  Group,
  InstancedMesh,
  Matrix4,
  Mesh,
  MeshBasicMaterial,
  Quaternion,
  ShaderMaterial,
  SphereGeometry,
  Vector3,
  type PerspectiveCamera,
} from 'three';
import type { CameraPose, Materials, Palette, ScreenPoint } from '../core/types';

export interface LandDots {
  /** flat [lat0, lon0, lat1, lon1, …] */
  points: number[];
  count: number;
}

let landCache: Promise<LandDots> | null = null;
/** Lazily import the land-dot asset (cached per page). */
export function loadLandDots(): Promise<LandDots> {
  landCache ??= import('../../data/geo/land-dots.json').then((m) => (m.default ?? m) as unknown as LandDots);
  return landCache;
}

const DEG = Math.PI / 180;
export function latLonToVec3(lat: number, lon: number, radius = 1, out = new Vector3()): Vector3 {
  const c = Math.cos(lat * DEG);
  return out.set(radius * c * Math.sin(lon * DEG), radius * Math.sin(lat * DEG), radius * c * Math.cos(lon * DEG));
}
export function vec3ToLatLon(v: Vector3): { lat: number; lon: number } {
  const r = v.length() || 1;
  return { lat: Math.asin(v.y / r) / DEG, lon: Math.atan2(v.x, v.z) / DEG };
}

export interface GlobeMarker {
  id: string;
  lat: number;
  lon: number;
  color?: Color;
  /** Pillar height (world units, default 0.04). */
  height?: number;
  /** Pillar radius (default 0.008). */
  size?: number;
}

export interface GlobeOptions {
  materials: Materials;
  palette: Palette;
  radius?: number;
  /** Fraction of land dots to keep (quality tiers: 1 / 0.6 / 0.4). */
  density?: number;
  /** Dot radius relative to globe radius. Default 0.0072. */
  dotSize?: number;
  /** Max markers. Default 512. */
  markerCapacity?: number;
}

const ATMO_VERT = /* glsl */ `
varying vec3 vN;
varying vec3 vV;
void main() {
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  vN = normalize(normalMatrix * normal);
  vV = normalize(-mv.xyz);
  gl_Position = projectionMatrix * mv;
}`;
const ATMO_FRAG = /* glsl */ `
uniform vec3 uColor;
uniform float uStrength;
uniform float uLimb;
varying vec3 vN;
varying vec3 vV;
void main() {
  // Back faces of a slightly larger sphere: brightest just outside the globe's limb (|N·V| ≈ uLimb),
  // fading to zero at the halo's own silhouette (N·V → 0).
  float d = clamp(abs(dot(vN, vV)) / uLimb, 0.0, 1.0);
  float f = d * d * (3.0 - 2.0 * d);
  gl_FragColor = vec4(uColor, f * f * uStrength);
  #include <colorspace_fragment>
}`;

const up = new Vector3(0, 1, 0);
const zAxis = new Vector3(0, 0, 1);
const m4 = new Matrix4();
const q = new Quaternion();
const s3 = new Vector3(1, 1, 1);
const p3 = new Vector3();
const n3 = new Vector3();

export class Globe {
  readonly group = new Group();
  readonly radius: number;
  private ocean: Mesh<SphereGeometry, MeshBasicMaterial>;
  private dots: InstancedMesh<CircleGeometry, MeshBasicMaterial>;
  private atmo: Mesh<SphereGeometry, ShaderMaterial>;
  private markers: InstancedMesh<CylinderGeometry, MeshBasicMaterial>;
  private markerList: GlobeMarker[] = [];
  private markerTops: Vector3[] = [];
  private markerPoints: ScreenPoint[] = [];

  static async create(opts: GlobeOptions): Promise<Globe> {
    const land = await loadLandDots();
    return new Globe(opts, land);
  }

  private constructor(opts: GlobeOptions, land: LandDots) {
    const r = (this.radius = opts.radius ?? 1);
    const { materials } = opts;
    this.group.name = 'Globe';

    this.ocean = new Mesh(new SphereGeometry(r * 0.995, 64, 48), materials.basic((p) => oceanColor(p)));
    this.group.add(this.ocean);

    const keep = Math.max(0.05, Math.min(1, opts.density ?? 1));
    const total = land.count;
    const n = Math.floor(total * keep);
    const dotGeo = new CircleGeometry(r * (opts.dotSize ?? 0.0072) * (keep < 1 ? 1 / Math.sqrt(keep) ** 0.5 : 1), 6);
    this.dots = new InstancedMesh(dotGeo, materials.basic((p) => dotColor(p)), n);
    const step = total / Math.max(1, n);
    for (let i = 0; i < n; i++) {
      const k = Math.floor(i * step);
      const lat = land.points[k * 2] ?? 0;
      const lon = land.points[k * 2 + 1] ?? 0;
      latLonToVec3(lat, lon, r * 1.0005, p3);
      n3.copy(p3).normalize();
      q.setFromUnitVectors(zAxis, n3);
      this.dots.setMatrixAt(i, m4.compose(p3, q, s3));
    }
    this.dots.instanceMatrix.needsUpdate = true;
    this.dots.computeBoundingSphere();
    this.group.add(this.dots);

    const halo = 1.09;
    this.atmo = new Mesh(
      new SphereGeometry(r * halo, 48, 32),
      new ShaderMaterial({
        vertexShader: ATMO_VERT,
        fragmentShader: ATMO_FRAG,
        uniforms: {
          uColor: { value: new Color() },
          uStrength: { value: 0.55 },
          uLimb: { value: Math.sqrt(1 - 1 / (halo * halo)) },
        },
        side: BackSide,
        transparent: true,
        depthWrite: false,
        blending: AdditiveBlending,
        toneMapped: false,
      }),
    );
    this.group.add(this.atmo);

    const cap = opts.markerCapacity ?? 512;
    const mg = new CylinderGeometry(1, 1, 1, 8, 1);
    mg.translate(0, 0.5, 0);
    this.markers = new InstancedMesh(mg, new MeshBasicMaterial({ toneMapped: false }), cap);
    this.markers.count = 0;
    this.group.add(this.markers);
    this.setPalette(opts.palette);
  }

  /** Re-tint for a theme change (dots/ocean follow the material registry automatically). */
  setPalette(p: Palette): void {
    this.atmo.visible = p.theme === 'dark';
    this.atmo.material.uniforms['uColor']!.value.copy(p.flow).lerp(p.fg, 0.25);
  }

  /** Place pillar markers; markers in the same 0.25° bucket stack along the normal. */
  setMarkers(list: readonly GlobeMarker[]): void {
    const cap = this.markers.instanceMatrix.count;
    this.markerList = list.slice(0, cap);
    this.markerTops = [];
    this.markerPoints = [];
    const stacks = new Map<string, number>();
    const white = new Color(1, 1, 1);
    this.markerList.forEach((mk, i) => {
      const key = `${Math.round(mk.lat * 4)}:${Math.round(mk.lon * 4)}`;
      const base = stacks.get(key) ?? 0;
      const h = mk.height ?? 0.04;
      stacks.set(key, base + h + 0.004);
      const w = mk.size ?? 0.008;
      latLonToVec3(mk.lat, mk.lon, this.radius + base, p3);
      n3.copy(p3).normalize();
      q.setFromUnitVectors(up, n3);
      this.markers.setMatrixAt(i, m4.compose(p3, q, new Vector3(w, h, w)));
      this.markers.setColorAt(i, mk.color ?? white);
      const top = n3.clone().multiplyScalar(this.radius + base + h);
      this.markerTops.push(top);
      this.markerPoints.push({ position: top, id: mk.id });
    });
    this.markers.count = this.markerList.length;
    this.markers.instanceMatrix.needsUpdate = true;
    if (this.markers.instanceColor) this.markers.instanceColor.needsUpdate = true;
    this.markers.computeBoundingSphere();
  }

  /** Marker top positions with ids, for `ctx.picker.addPoints(() => globe.points())`. */
  points(): readonly ScreenPoint[] {
    return this.markerPoints;
  }

  markerTop(i: number): Vector3 | undefined {
    return this.markerTops[i];
  }

  /** True when a world point on/above the surface faces away from the camera. */
  isBehind(world: Vector3, camera: PerspectiveCamera): boolean {
    n3.copy(world).normalize();
    p3.copy(camera.position).sub(world);
    return n3.dot(p3) < 0;
  }

  /** Camera pose looking at (lat, lon) from `distance` (world units from the centre). */
  poseFor(lat: number, lon: number, distance = 3.2): CameraPose {
    return { position: latLonToVec3(lat, lon, distance), target: [0, 0, 0] };
  }

  dispose(): void {
    for (const m of [this.ocean, this.dots, this.atmo, this.markers]) {
      m.geometry.dispose();
      const mat = m.material as { dispose(): void };
      mat.dispose();
    }
    this.markers.dispose();
    this.dots.dispose();
    this.group.removeFromParent();
  }
}

function oceanColor(p: Palette): Color {
  return p.bg.clone().lerp(p.theme === 'dark' ? p.coolant : p.grid, p.theme === 'dark' ? 0.12 : 0.35);
}
function dotColor(p: Palette): Color {
  return p.theme === 'dark' ? p.muted.clone().lerp(p.fg, 0.25) : p.muted.clone().lerp(p.bg, 0.15);
}
